function readyButton(label){
 return [...document.querySelectorAll('button')].find(b=>{
  const style=getComputedStyle(b),box=b.getBoundingClientRect();
  const matches=typeof label==='string'?b.textContent.trim()===label:label.parts.every(part=>b.textContent.includes(part));
  return matches&&!b.disabled&&style.visibility!=='hidden'&&style.display!=='none'&&Number(style.opacity)>0&&box.width>0&&box.height>0;
 })||false;
}
async function waitForMailButton(frame,label){
 // Opaque-frame readiness restores parent-owned references asynchronously after remount.
 const handle=await frame.waitForFunction(readyButton,{timeout:15000,polling:'raf'},label);
 const button=handle.asElement();assert(button,'Visible enabled '+label);return button;
}
