  const replyPath='/api/secureshop/email/auto-reply/'+seed.thread_id;let capturedReply;cdp=await page.createCDPSession();cdp.on('Fetch.requestPaused',async event=>{if(new URL(event.request.url).pathname===replyPath){try{assert.equal(capturedReply,undefined,'Duplicate reply response');const raw=await cdp.send('Fetch.getResponseBody',{requestId:event.requestId});capturedReply=decodeReplyCapture(event,raw,{origin,path:replyPath,requestId:posts.find(p=>p.path===replyPath)?.body.requestId});}catch(error){failure=error;}finally{await cdp.send('Fetch.continueRequest',{requestId:event.requestId}).catch(error=>{failure=error;});}return;}try{if(event.responseStatusCode===200){const raw=await cdp.send('Fetch.getResponseBody',{requestId:event.requestId}),value=JSON.parse(Buffer.from(raw.body,raw.base64Encoded?'base64':'utf8').toString());if(value.judgment?.verdict==='unavailable')parent=value;if(value.completed===true&&!lost){child=value;lost=true;await cdp.send('Fetch.fulfillRequest',{requestId:event.requestId,responseCode:502,responseHeaders:[{name:'content-type',value:'application/json'}],body:Buffer.from('{"error":"Controlled response loss"}').toString('base64')});return;}}await cdp.send('Fetch.continueRequest',{requestId:event.requestId});}catch(e){failure=e;await cdp.send('Fetch.failRequest',{requestId:event.requestId,errorReason:'Failed'}).catch(()=>{});}});await cdp.send('Fetch.enable',{patterns:[{urlPattern:origin+'/api/secureshop/email/header-assessment',requestStage:'Response'},{urlPattern:origin+replyPath,requestStage:'Response'}]});
