function interceptSubject(original,ownAddress){assert.equal(original.from,ownAddress);assert.equal(original.to,ownAddress);assert.match(original.requestId,/^[0-9a-f-]{36}$/i);assert.equal(original.subject,'Controlled header');const modified={...original,subject:'Controlled header\r\nX-Training: full-index'};assert.deepEqual({...modified,subject:original.subject},original);return modified;}
function decodeReplyCapture(event,raw,expected){assert.equal(event.request.url,expected.origin+expected.path);assert.equal(event.request.method,'POST');assert.equal(event.responseStatusCode,200);const request=JSON.parse(event.request.postData);assert.match(expected.requestId||'',/^[0-9a-f-]{36}$/i);assert.equal(request.requestId,expected.requestId);const body=Buffer.from(raw.body,raw.base64Encoded?'base64':'utf8').toString();assert(Buffer.byteLength(body)<=16384);const reply=JSON.parse(body);assert.equal(reply.requestId,request.requestId);assert.equal(reply.status,'saved');return{request,reply,rawBody:body};}
module.exports={decodeReplyCapture,composeClosed,interceptSubject,qualifyMailHeaderBrowser,waitForMailButton,readyButton};
